import sys

def minInsAndDel(A, B, N, M):
    # Create a mapping from value to index for array B
    # Since B is sorted and has distinct elements, this is straightforward
    val_to_idx = {val: i for i, val in enumerate(B)}

    # Filter A to keep only elements present in B, and replace them with their indices in B
    # This transforms the problem into finding the Longest Increasing Subsequence (LIS)
    # of these indices, because B is sorted.
    subseq = []
    for x in A:
        if x in val_to_idx:
            subseq.append(val_to_idx[x])

    # Compute LIS of subseq using O(K log K) approach where K is length of subseq
    if not subseq:
        lis_len = 0
    else:
        tails = []
        for x in subseq:
            # Binary search for the first element in tails >= x
            left, right = 0, len(tails)
            while left < right:
                mid = (left + right) // 2
                if tails[mid] < x:
                    left = mid + 1
                else:
                    right = mid

            if left == len(tails):
                tails.append(x)
            else:
                tails[left] = x
        lis_len = len(tails)

    # Minimum operations = deletions + insertions
    # Deletions: elements in A not part of the common subsequence = N - lis_len
    # Insertions: elements in B not part of the common subsequence = M - lis_len
    # Total = (N - lis_len) + (M - lis_len) = N + M - 2 * lis_len
    return N + M - 2 * lis_len

def main():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    try:
        N = int(next(iterator))
        M = int(next(iterator))

        A = []
        for _ in range(N):
            A.append(int(next(iterator)))

        B = []
        for _ in range(M):
            B.append(int(next(iterator)))

        result = minInsAndDel(A, B, N, M)
        print(result)
    except StopIteration:
        pass

if __name__ == "__main__":
    main()
